import { cva } from "class-variance-authority";
import type { StepStatus } from "./step-status";

/** Visual style for vertical stepper indicators. */
export type StepperVariant = "ascii" | "numbered" | "bullet" | "tag" | "progress";

/** Stepper layout orientation. */
export type StepperOrientation = "vertical" | "horizontal";

/** Root variants for vertical steppers. */
export const stepperRootVariants = cva("flex flex-col list-none m-0 p-0 font-mono", {
  variants: {
    variant: {
      ascii: "[counter-reset:step] gap-0",
      numbered: "[counter-reset:step] gap-0",
      bullet: "gap-0",
      tag: "gap-1",
      progress: "gap-0",
    },
  },
  defaultVariants: { variant: "ascii" },
});

/**
 * Step row layout for vertical steppers. Single column: the trigger owns the indicator/label row
 * internally, and StepperContent stacks underneath it. A two-column track put expanded content
 * beside the trigger instead of below it.
 */
export const stepperStepVariants = cva(
  "relative grid grid-cols-1 items-start py-4 [counter-increment:step]",
);

/** Indicator variants for vertical steppers. */
export const stepperIndicatorVariants = cva(
  "inline-flex shrink-0 font-mono tabular-nums leading-[1.4] select-none",
  {
    variants: {
      variant: {
        ascii: "text-[13px] font-semibold whitespace-nowrap",
        numbered:
          "w-5 h-5 items-center justify-center text-[11px] font-semibold border " +
          "border-border-strong bg-background text-muted-foreground",
        bullet: "w-[1ch] text-[14px] font-semibold justify-center",
        tag:
          "min-w-[72px] px-2 py-[2px] items-center justify-center text-2xs font-semibold " +
          "uppercase tracking-[0.08em] border border-border-strong text-muted-foreground",
        progress: "text-[13px] font-semibold leading-none tracking-[-0.04em] text-border-strong",
      },
      status: {
        pending: "",
        active: "",
        completed: "",
        error: "",
        skipped: "",
        disabled: "",
      },
    },
    compoundVariants: [
      // Completed reads --primary, not --success: progress is a neutral control state, and the
      // status palette stays reserved for meaning (error keeps --error). --primary is monochrome
      // in both themes, so completed steps look the same in dark and light.
      // ASCII — color the glyph by state.
      { variant: "ascii", status: "completed", className: "text-primary" },
      { variant: "ascii", status: "active", className: "text-foreground" },
      { variant: "ascii", status: "error", className: "text-error" },
      { variant: "ascii", status: "skipped", className: "text-muted-foreground opacity-60" },
      { variant: "ascii", status: "disabled", className: "text-muted-foreground opacity-40" },

      // Numbered — invert active, fill completed/error, dashed skipped, dim disabled.
      {
        variant: "numbered",
        status: "completed",
        className: "bg-primary border-primary text-primary-foreground",
      },
      {
        variant: "numbered",
        status: "active",
        className: "bg-foreground border-foreground text-background",
      },
      {
        variant: "numbered",
        status: "error",
        className: "bg-error border-error text-background",
      },
      { variant: "numbered", status: "skipped", className: "border-dashed" },
      { variant: "numbered", status: "disabled", className: "opacity-40" },

      // Bullet — single glyph color swap.
      { variant: "bullet", status: "completed", className: "text-primary" },
      { variant: "bullet", status: "active", className: "text-foreground" },
      { variant: "bullet", status: "error", className: "text-error" },
      { variant: "bullet", status: "skipped", className: "text-muted-foreground opacity-60" },
      { variant: "bullet", status: "disabled", className: "text-muted-foreground opacity-40" },

      // Tag — color the border + label, invert active with bg-foreground.
      {
        variant: "tag",
        status: "completed",
        className: "text-primary border-primary",
      },
      {
        variant: "tag",
        status: "active",
        className: "bg-foreground border-foreground text-background",
      },
      {
        variant: "tag",
        status: "error",
        className: "text-error border-error",
      },
      {
        variant: "tag",
        status: "skipped",
        className: "border-dashed text-muted-foreground",
      },
      { variant: "tag", status: "disabled", className: "opacity-40" },

      // Progress — Unicode block bar color swap.
      { variant: "progress", status: "completed", className: "text-primary" },
      { variant: "progress", status: "active", className: "text-foreground" },
      { variant: "progress", status: "error", className: "text-error" },
      { variant: "progress", status: "skipped", className: "text-muted-foreground opacity-60" },
      { variant: "progress", status: "disabled", className: "text-muted-foreground opacity-40" },
    ],
    defaultVariants: { variant: "ascii", status: "pending" },
  },
);

/** Label variants for vertical steppers. */
export const stepperLabelVariants = cva("text-[13px] leading-[1.4] font-medium", {
  variants: {
    status: {
      pending: "text-muted-foreground",
      active: "text-foreground font-semibold",
      completed: "text-foreground",
      error: "text-error font-semibold",
      skipped: "text-muted-foreground line-through",
      disabled: "text-muted-foreground opacity-50",
    },
  },
  defaultVariants: { status: "pending" },
});

/** Button-like trigger variants for interactive stepper rows. */
export const stepperTriggerVariants = cva(
  "flex items-start gap-2.5 appearance-none bg-transparent border-0 text-left w-full " +
    "px-0 py-2 -my-2 pointer-coarse:my-0 pointer-coarse:min-h-11 " +
    "font-[inherit] cursor-pointer rounded-none " +
    "focus-visible:outline-2 focus-visible:outline-ring focus-visible:outline-offset-2 " +
    "disabled:cursor-not-allowed " +
    "aria-disabled:cursor-not-allowed aria-disabled:opacity-60",
);

/** Status glyphs for non-numbered vertical stepper variants. The ascii active glyph is rendered as JSX. */
export const STEP_INDICATOR_GLYPHS: Record<
  Exclude<StepperVariant, "numbered">,
  Record<StepStatus, string>
> = {
  ascii: {
    completed: "[x]",
    active: "", // rendered as JSX with blinking cursor
    pending: "[ ]",
    error: "[!]",
    skipped: "[—]",
    disabled: "[/]",
  },
  bullet: {
    completed: "•",
    active: "›",
    pending: "·",
    error: "×",
    skipped: "—",
    disabled: "·",
  },
  tag: {
    completed: "DONE",
    active: "RUN",
    pending: "WAIT",
    error: "FAIL",
    skipped: "SKIP",
    disabled: "OFF",
  },
  progress: {
    completed: "███",
    active: "█▌░",
    pending: "░░░",
    error: "!!!",
    skipped: "———",
    disabled: "···",
  },
};

/** Completed glyph for numbered steppers. */
export const NUMBERED_COMPLETED_GLYPH = "✓";
/** Error glyph for numbered steppers. */
export const NUMBERED_ERROR_GLYPH = "!";
/** Skipped glyph for numbered steppers. */
export const NUMBERED_SKIPPED_GLYPH = "—";
/** Disabled glyph for numbered steppers. */
export const NUMBERED_DISABLED_GLYPH = "·";

/*
 * Stepper variant CSS contract.
 *
 * Three things live in real CSS (not Tailwind utilities):
 *
 *   1. The `ascii` active-state blinking cursor (custom @keyframes). Wrapped
 *      in motion-safe Tailwind utility on the consuming side; the keyframes
 *      themselves are declared here.
 *   2. The `numbered` variant's CSS counter — the digit shown in pending and
 *      active states comes from `counter(step)` rendered through `::before`
 *      on the indicator span. Tailwind's arbitrary value support for
 *      `content-[counter(...)]` is unreliable across compilers.
 *   3. The vertical connector line between steps. Composed via utilities the
 *      connector clamped to a 2px sliver because `bottom: 0` plus a 30px
 *      `<li>` left no room to draw. Real CSS lets the line overshoot the
 *      `<li>` boundary so it visually bridges into the next indicator at any
 *      row height. The `left` offset is variant-specific and centred on the
 *      indicator column width (1ch ASCII → centred on the `x` in `[x]`, 20px
 *      numbered square → centred at 10px, 1ch bullet → centred at 4px).
 */

@keyframes stepper-blink {
  50% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  /*
   * Keep the cursor visible but stop animating it. The .motion-safe: utility
   * on the consumer prevents the animation property from being set in the
   * first place, but this guard catches any direct usage of the keyframes
   * elsewhere.
   */
  [data-variant="ascii"] [data-stepper-cursor] {
    /* biome-ignore lint/complexity/noImportantStyles: prefers-reduced-motion override must defeat the cursor keyframes regardless of specificity. */
    animation: none !important;
  }
}

/*
 * Numbered indicator: render `counter(step)` for pending and active cells.
 * Completed/error/skipped/disabled render an explicit glyph in JSX and the
 * counter span is absent from the tree.
 *
 * The CSS counter is established on the <ol data-variant="numbered"> via the
 * `[counter-reset:step]` Tailwind utility and incremented on each <li> via
 * `[counter-increment:step]`. This rule paints the digit on the indicator
 * span whose JSX renders an empty `[data-counter]` placeholder.
 */
[data-variant="numbered"] [data-counter]::before {
  content: counter(step);
}

/*
 * Vertical connector — shared geometry for ASCII, numbered, and bullet
 * variants. `tag` and `progress` opt out (no rule). The `<li>` itself is
 * positioned `relative` via the Tailwind base. Scoped to
 * `[data-orientation="vertical"]` so the horizontal stepper's numbered
 * variant (which has its own behind-the-square horizontal bar) is untouched.
 *
 * `top: 36px` clears the indicator glyph (sits at row top with `py-4`, so
 * the glyph bottom edge lands at ~34px and the connector starts ~2px below).
 * `bottom: -8px` overshoots the `<li>` boundary modestly so the line visually
 * bridges into the next step's connector without dominating the row height —
 * the row breathes around a short connector segment rather than a long line.
 * The last step suppresses the connector.
 */
[data-orientation="vertical"][data-variant="ascii"] > li:not(:last-child)::before,
[data-orientation="vertical"][data-variant="numbered"] > li:not(:last-child)::before,
[data-orientation="vertical"][data-variant="bullet"] > li:not(:last-child)::before {
  content: "";
  position: absolute;
  top: 36px;
  bottom: -8px;
  width: 1px;
  background: var(--border);
}

/*
 * Per-variant horizontal alignment of the connector. Each value centres the
 * 1px line on the visual middle of the indicator column.
 */
[data-orientation="vertical"][data-variant="ascii"] > li:not(:last-child)::before {
  /* `[x]` is 3 mono chars wide; centre on the `x` (1.5ch from the left edge). */
  left: calc(1.5ch + 0.5px);
}

[data-orientation="vertical"][data-variant="numbered"] > li:not(:last-child)::before {
  /* 20px square indicator → centre at 10px (½px nudge keeps the 1px line crisp). */
  left: 9.5px;
  /* Square bottom sits at ~36px (16px paddingTop + 20px square). Push the
   * connector start 2px below the square so it doesn't paint over the border. */
  top: 38px;
}

[data-orientation="vertical"][data-variant="bullet"] > li:not(:last-child)::before {
  /* 1ch indicator → centre at ½ch. Dashed style differentiates the low-chrome variant. */
  left: calc(0.5ch + 0.5px);
  background: transparent;
  border-left: 1px dashed var(--border);
  width: 0;
}

/*
 * Completed steps recolour the connector so a finished segment reads as a
 * filled timeline. `--primary` (not `--success`): progress is a neutral control
 * state and stays monochrome in both palettes; the status palette is reserved
 * for meaning. Bullet uses `border-left-color` because the connector is a
 * border, not a background.
 */
[data-orientation="vertical"][data-variant="ascii"]
  > li[data-status="completed"]:not(:last-child)::before,
[data-orientation="vertical"][data-variant="numbered"]
  > li[data-status="completed"]:not(:last-child)::before {
  background: var(--primary);
}

[data-orientation="vertical"][data-variant="bullet"]
  > li[data-status="completed"]:not(:last-child)::before {
  border-left-color: var(--primary);
}

/*
 * Substep branch rail. Substeps render below their parent trigger, indented by
 * StepperContent. Without a connector they read as a detached second block, so
 * each row draws the terminal `├─` branch (and `└─` on the last row) from the
 * parent's indent line: a 1px vertical rail plus a short tee into the row.
 * Pure CSS because the geometry is `::before`/`::after` positioning with a
 * `:last-child` stub, not a variant axis.
 */
[data-slot="stepper-substep"] {
  position: relative;
  padding-left: 14px;
}

[data-slot="stepper-substep"]::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--border);
}

/* Last row: the rail stops at the tee, closing the branch as `└`. */
[data-slot="stepper-substep"]:last-child::before {
  bottom: 50%;
}

[data-slot="stepper-substep"]::after {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  width: 8px;
  height: 1px;
  background: var(--border);
}
